import utilSrv from "./utils"
import apiCore from "./apicore";
import {loadCookie} from "./cookie"
import {captureVisible, downloadVideo,
     downloadMedia, saveASFile, sendTabMessage} from "./capture"
import {xIsLogin} from "./request"
import { initMessagePort } from "./cb-ffmpeg"
import {CacheSrv} from "../index-db/cache.srv"
import {MediaSrv} from "../index-db/media.srv"
import {ItemsSrv} from "../index-db/items.srv"
import {CommentsSrv} from "../index-db/comments.srv"
import {doSetNetRolePolicy, ocHeartBeat} from "./worker"

export default (function(){
    const cacheSrv = new CacheSrv();
    const mediaSrv = new MediaSrv();
    const itemsSrv = new ItemsSrv();
    const commentsSrv = new CommentsSrv();
    var messageSrv = {_octimer:[]}; //定义消息的监听逻辑

    //数据清理的逻辑
    const clearData = async(refType, url) => {
        if (refType === 0) {//清理数据
            await cacheSrv.ClearCache('');
            await itemsSrv.clear();//清理采集
        } else if (refType === 1) {//清理任务
            await cacheSrv.ClearCache('task');
        } else if (refType === 5) {//清理任务
            await cacheSrv.DomainReset(url);
        } else if (refType === 3) {
            await mediaSrv.clear(url, 1);
        } else if (refType === 4) {
            await mediaSrv.clear(url, 2);
        } else {
            await mediaSrv.clear(url, 0);
        }
    };

    //添加到offscreen数据信息
    messageSrv.PushOcTimer = (timer=0, fn=()=>{})=>{
        messageSrv._octimer.push({timer:timer, fn:fn});
    };
     //通过offscreen维持心跳
    messageSrv.doOffScreenHeartBeat = (loop=0) => {
        const params = {type:utilSrv.msgHBOffScreen, timer:loop};
        chrome.runtime.sendMessage(params, async(response) => {
            utilSrv.Write(utilSrv.INFO, "offscreen heartbeat ", response);
        });
    };
    //监听全部的bgScript的消息处理池
    messageSrv.doListenMessageDispatch = async()=>{//任务监听处理逻辑
        //这里不要使用异步async，否则会有适配的bug
        const bFFmpeg = initMessagePort();
        chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
            utilSrv.Write(utilSrv.INFO, "GB消息接收", message, sender, sendResponse);
            if (!message || !message.type) {//消息为空的情况
                sendResponse(null);//返回数据
                return false;
            }
             // 使用 then/catch 代替 async/await
            if (message.type && message.type == utilSrv.msgTypeDispatchTask) {//任务消息
                cacheSrv.TabCache(message.link)
                    .then(task => {
                        utilSrv.Write(utilSrv.INFO, "任务派发调度", message, task);
                        sendResponse(task);
                    })
                    .catch(error => {
                        utilSrv.Write(utilSrv.ERROR, "获取任务失败", error);
                        sendResponse(null);
                    });   
                return true;   
            } else if (message.type && message.type == utilSrv.msgTypeApiProxy) {
                if (message.apiURL === '/items-local-db') {//本地保存的情况
                    itemsSrv.Push(message.params).then(()=>{
                        sendResponse("OK");//返回数据
                    });
                    return true;
                } else if (message.apiURL === '/comments-local-db') {//本地保存的情况
                    commentsSrv.Push(message.params).then(()=>{
                        sendResponse("OK");//返回数据
                    });
                    return true;
                } else if(xIsLogin()) {//登录的情况
                    apiCore.SetCallback(message.params).then(()=>{
                        sendResponse("OK");//返回数据
                    });//发起网络请求
                    return true;
                }
                return false;
            } else if (message.type && message.type == utilSrv.msgTypeGetScript) {
                apiCore.GetScript(message.uuid, message.from).then((sxData)=>{
                    sendResponse(sxData? sxData.script:'');//返回数据
                }).catch((error)=>{
                    utilSrv.Write(utilSrv.ERROR, "获取脚本失败", error);
                    sendResponse('');//返回数据
                });
                return true;
            } else if (message.type && message.type == utilSrv.msgTypeCaptureVisible) {
                captureVisible(sendResponse);
                return true;
            } else if(message.type && message.type == utilSrv.msgTypeDownloadVideos) {
                downloadVideo(message.link, message.title, sendResponse).then(()=>{
                    sendResponse("OK");//返回数据
                });
                return true;
            } else if(message.type && message.type == utilSrv.msgTypeDownloadMedia) {
                downloadMedia(message.image, message.video, message.title, sendResponse).then(()=>{
                    sendResponse("OK");//返回数据
                });
                return true;
            } else if (message.type && message.type == utilSrv.msgTypeClearCache) {
                clearData(message.refType, message.link).then(()=>{
                    sendResponse('OK');
                }).catch((err)=>{
                    sendResponse('Fail');
                    utilSrv.Write(utilSrv.ERROR, "数据清理移除", message, err);
                });
                return true;
            } else if (message.type && message.type == utilSrv.msgTypeTaskCount) {
                cacheSrv.Count().then((res)=>{
                    sendResponse(res);
                }).catch((err)=>{
                    utilSrv.Write(utilSrv.ERROR, "数据获取移除", message, err);
                    sendResponse(-1);
                });
                return true;
            } else if (message.type && message.type == utilSrv.msgTypeInsertMedia) {
                const {url, status, ref_type, items} = message.data;
                if (!items || !Array.isArray(items)) {
                    sendResponse('Fail');
                    return false;
                }
                mediaSrv.Push(url, status, ref_type, items).then((res)=>{
                    sendResponse(res);
                }).catch((err)=>{
                    utilSrv.Write(utilSrv.ERROR, "媒体插入异常", message, err);
                    sendResponse('Fail');
                });
                return true;
            } else if (message.type && message.type == utilSrv.msgHBOffScreen) {
                const loop = message.timer;
                for (let i = 0; i < messageSrv._octimer.length; i++) {
                    const ocTasker = messageSrv._octimer[i];
                    if (loop % ocTasker.timer == 0 && ocTasker.fn) {
                        utilSrv.Write(utilSrv.INFO, "执行offscreen任务调度", ocTasker.fn);
                        ocTasker.fn();//执行注册的回调
                    }
                }
                sendResponse("OK");//返回数据
                return false;
            } else if(message.type && message.type == utilSrv.msgTabNotifyMsg) {//消息转发tab消息
                sendTabMessage(message.tabId, message.data).then(()=>{
                    sendResponse("OK");//返回数据
                }).catch((err)=>{
                    utilSrv.Write(utilSrv.ERROR, "tab消息转发", message, err);
                    sendResponse('Fail');
                });
                return true;
            } else if (message.type == utilSrv.msgTypeCookie && message.domain) {//回传cookie的业务逻辑
                loadCookie(message.domain, message.cookie).then((cookieItems)=>{
                    const params = {cookie: cookieItems.join(';'),
                        domain: message.domain, user_agent:message.agent};
                    apiCore.SetCookie(params);
                    sendResponse("OK");//返回数据
                }).catch((err)=>{
                    utilSrv.Write(utilSrv.ERROR, "Cookie消息异常", err);
                });
                return true;
            } else  if (message.type == utilSrv.msgTypeFingerPrint && message.domain) {//回传指纹的业务逻辑
                loadCookie(message.domain, message.cookie).then((cookieItems)=>{
                    const meta = {cookie: cookieItems.join(';'), user_agent:message.agent};
                    const sKey = 'cookie@'+message.domain;
                    cacheSrv.SetCache(sKey, 'cookie', meta);
                    sendResponse("OK");//返回数据
                }).catch((err)=>{
                    utilSrv.Write(utilSrv.ERROR, "FingerPrint消息异常", err);
                });
                return true;
            } else if (message.type == utilSrv.msgTypeNetRule) { //网络规则设定
                doSetNetRolePolicy(message.link).then(()=>{
                    sendResponse("OK");//返回数据
                });
                return true;
            } else if (message.type == utilSrv.msgTypeSTARTMERGE) {
                ocHeartBeat().then(()=>{//初始化建立消息管道
                    bFFmpeg.init(sender).then(()=>{
                        sendResponse("OK");//返回数据
                    }); 
                });
                return true;
            } else if(message.type === utilSrv.msgTypeBRIDGEREADY) {
                bFFmpeg.ready().then(()=>{
                    sendResponse("OK");//返回数据
                }); //桥接管道准备就绪
                return true;
            } else if (message.type == utilSrv.msgTypeFFmpegMergeDone) {//执行下载导出逻辑
                saveASFile(message.url, message.title+'视频下载', '.mp4');
                setTimeout(()=>{//等待导出完成
                    sendResponse("OK");//返回数据
                }, 500);
                return true;
            } else {//默认返回
                return false
            }
        });
    };
    return messageSrv;
})();