import { connection } from "./idb-conn";
import { indexDB } from "./idb-schema";
import utilSrv from "@/static/js/base/utils";

export const initJsStore = async () => {
    const result = await connection.initDb(indexDB);
    utilSrv.Write(utilSrv.INFO, "初始化数据库", result);
    return result;
};