import utilSrv from "./utils"
import {MediaSrv} from "../index-db/media.srv"
import { MediaRefType } from "@/static/js/index-db/idb-schema";

//获取tab发送消息的逻辑
export async function sendTabMessage(tabId, data) {
  var link = '';
  if (tabId < 1) {//提取标签的ID
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab && tab.id) {
      tabId = tab.id;
      link  = tab.url;
    }
  }
  utilSrv.Write(utilSrv.INFO, "tab转发", tabId, link, data);
  try {
    const state = await new Promise((resolve, reject) => {
      chrome.tabs.sendMessage(tabId, data, (response) => {
        // 必须检查 lastError，否则错误会被静默吞掉
        if (chrome.runtime.lastError) {
            reject(new Error(chrome.runtime.lastError.message));
        } else {
            resolve(response);
        }
      });
    });
    return state;
  } catch (err) {
    utilSrv.Write(utilSrv.ERROR, "发送消息异常", err);
    return false;
  }
}

// 截图可见区域
export function captureVisible(sendResponse) {
  chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
    if (!tabs || !tabs.length) {
      sendResponse({ code: 404, error: '未找到活动标签页' });
      return;
    }
    const tab = tabs[0];
    chrome.tabs.captureVisibleTab(tab.windowId, { format: 'png' }, async (dataUrl) => {
      if (chrome.runtime.lastError) {
        sendResponse({ code: 500, error: chrome.runtime.lastError.message });
        return;
      }
      await downloadFile(dataUrl, '截图_可见区域', ".png");
      sendResponse({ code: 0 });
    });
  });
}

// 截图可见区域
export async function downloadVideo(link, title, sendResponse) {
  const mediaSrv = new MediaSrv();
  const items = await mediaSrv.GetList(1, 2, MediaRefType.video, link);
  if (!items || items.length < 1) {
    sendResponse({ code: 404, error: '未抓取视频地址' });
    return;
  }
  const includeRegex = /\.(mp4|webm|ogv|flv)$/i;
  let videos = items.filter(item => {
    const name = item.meta.src.split('/').pop();
    return includeRegex.test(name);
  });
  if (!videos || videos.length < 1) {
    videos = items;
  }
  title = title.replace(/[,;.\s]/g, '');
  const vReg = /\.(mp4|webm|ogv|flv|m3u8)(?:\?|#|$)/i;
  for (let idx = 0; idx < videos.length; idx++) {
    try {
      const dataUrl = videos[idx].meta.src;
      const match = dataUrl.match(vReg);
      const suffix= match ? '.'+match[1].toLowerCase():'.mp4';
      await downloadFile(dataUrl, title+'视频下载_', suffix);
      sendResponse({ code: 0 });
      break;
    } catch (err) {
      utilSrv.Write(utilSrv.ERROR, "下载失败", err);
    }
  }
}

//针对小红书适配成jpg格式
function xhsJpgImage(dataUrl) {
  let jpgUrl = '';
  const imgViewBase = 'https://sns-img-hw.xhscdn.com/';
  if (dataUrl.includes('webp_3') && dataUrl.includes('sns-webpic-qc.xhscdn.com')) {
    const sIndex = dataUrl.indexOf('!');
    if (sIndex && sIndex > 0) {
      const url = new URL(dataUrl.slice(0, sIndex));
      const segments = url.pathname.split('/').filter(Boolean);
      if (segments.length > 2) {
        jpgUrl = imgViewBase + segments.slice(2).join('/')+'?imageView2/2/w/format/jpg'
      }
    }
  }
  return jpgUrl;
}

//加载媒体数据信息
export async function downloadMedia(image, video, title, sendResponse) {
  title = title? title.replace(/[,;.\s]/g, ''):'';
  if (image && image.length > 0) {
    for (let i = 0; i < image.length; i++) {
      const dataUrl = image[i]; 
      let jpgUrl = xhsJpgImage(dataUrl);
      if (jpgUrl && jpgUrl.startsWith('http')) {
        try {
          await downloadFile(jpgUrl, title+'图片下载_['+i+']', '.jpg');
        } catch {//失败做一个补充动作
          await downloadFile(dataUrl, title+'图片下载_['+i+']', '.jpg');
        }
      } else {
        await downloadFile(dataUrl, title+'图片下载_['+i+']', '.jpg');
      }
    }
  }
  if (video && video.length > 0) {//视频的地址
    const vReg  = /\.(mp4|webm|ogv|flv|m3u8)(?:\?|#|$)/i;
    for (let i = 0; i < video.length; i++) {
      const dataUrl = video[i];
      const match = dataUrl.match(vReg);
      const suffix = match ? '.'+match[1].toLowerCase():'.mp4';
      try {
        await downloadFile(dataUrl, title+'视频下载_['+i+']', suffix);
        break;//视频只要下载一个即可
      } catch (e) {
        console.log(`地址 ${i} 下载失败，尝试下一个:`, dataUrl, e.message);
      }
    }
  }
  sendResponse({ code: 0 });
}

//格式化文件名的逻辑
function sanitizeFilename(filename, options = {}) {
  const { replacement = '_', maxLength = 200 } = options;

  if (typeof filename !== 'string' || filename.trim() === '') {
    return 'download';
  }

  let base = filename;
  let ext  = '';
  const lastDot = filename.lastIndexOf('.');
  if (lastDot > 0 && lastDot < filename.length - 1) {
    const maybeExt = filename.slice(lastDot + 1);
    if (/^[a-zA-Z0-9]{1,10}$/.test(maybeExt)) {
      base = filename.slice(0, lastDot);
      ext = '.' + maybeExt;
    }
  }

  base = base.replace(/[<>:"/\\|?*\u0000-\u001F]/g, replacement);

  base = base.replace(/^[\s.]+|[\s.]+$/g, '');
  if (replacement) {
    const esc = replacement.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    base = base.replace(new RegExp(`(${esc})+`, 'g'), replacement);
  }

  if (base.length > maxLength) {
    base = base.slice(0, maxLength);
  }
  if (!base) base = 'download';

  return base + ext;
}

// 下载文件另存为的操作
export function saveASFile(dataUrl, prefix, suffix) {
  const filename = `${prefix}_${Date.now()}${suffix}`;
  chrome.downloads.download({
      url: dataUrl,
      filename: sanitizeFilename(filename),
      saveAs: true,
    }, (result)=>{
      utilSrv.Write(utilSrv.INFO, "下载完成", result)
    });
}

// 下载文件（图片/视频通用），返回 Promise，resolve 表示下载完成，reject 表示失败
export function downloadFile(dataUrl, prefix, suffix) {
  return new Promise((resolve, reject) => {
    const dateStr = utilSrv.DateStr(0, 'YmdHis');
    const filename = `${prefix}_${dateStr}${suffix}`;
    chrome.downloads.download(
      {
        url: dataUrl,
        filename: sanitizeFilename(filename),
        saveAs: false,
      },
      (downloadId) => {
        // 1) 任务启动失败（URL 非法、被拦截等）
        if (chrome.runtime.lastError) {
          utilSrv.Write(utilSrv.ERROR, "下载启动失败", downloadId, chrome.runtime.lastError.message
          );
          reject(new Error(chrome.runtime.lastError.message));
          return;
        }

        // 2) 监听下载任务状态变化，拿到真正的结果
        const onChanged = (delta) => {
          if (delta.id !== downloadId) return;
          if (!delta.state) return;

          const state = delta.state.current;

          if (state === "complete") {
            chrome.downloads.onChanged.removeListener(onChanged);
            utilSrv.Write(utilSrv.INFO, "下载完成", downloadId, filename);
            resolve({ downloadId, filename, url: dataUrl });
          } else if (state === "interrupted") {
            chrome.downloads.onChanged.removeListener(onChanged);
            // 查询中断原因，403 -> 'SERVER_FORBIDDEN'
            chrome.downloads.search({ id: downloadId }, (items) => {
              const item = items && items[0];
              const err = (item && item.error) || "interrupted";

              utilSrv.Write(utilSrv.ERROR, "下载中断", downloadId, err);
              reject(new Error(err));
            });
          }
        };

        chrome.downloads.onChanged.addListener(onChanged);
      }
    );
  });
}