
export const UseChromeStore = function() {
    var _cache = {};
    this.Get = async function(key='') {
        const result = await chrome.storage.local.get([key]);
        if (result && result[key]) {
            return result[key];
        } 
        return (_cache[key])? _cache[key]:null;
    };
    this.Set = async function(key='', val='') {
        let item = {}; //对象
        item[key] = val;
        await chrome.storage.local.set(item);
        _cache[key] = val;
        return true; 
    };
    this.Remove = async function(key='') {
        _cache[key] = null;
        delete _cache[key];
        await chrome.storage.local.remove(key);
    };
}
