import alarmSrv from "./alarm"
import utilSrv from "../base/utils"
import apiCore from "../base/apicore"
import SBimsc from "../base/websocket"
import messageSrv from "../base/m-service"
import {UseChromeStore} from "../base/cache"
import {CacheSrv} from "../index-db/cache.srv"

export default (function(){
    const cacheSrv = new CacheSrv();
    const backgroundApp = {wsSrv:null, waitTask:-1};
    const doTaskExec = async(task={})=>{//运行任务
        if (!task || (!task.script && !task.script_uuid)) {
            return;//数据为空的情况
        }
        const tab = await chrome.tabs.create({url:task.link});
        if (task.timeout > 0) {//设置超时
            alarmSrv.tagRegister(tab.id, task.timeout);
        }
        await cacheSrv.SetTabCache(tab.id, task.link, task);
        if (task.is_window && task.is_window == 1) {//新窗口打开
            //state:chrome.windows.WindowState.MAXIMIZED
            //普通窗口即可，不用最大化，不然会遮挡
            await chrome.windows.create({tabId:tab.id});
        }
    };

    //任务的调度逻辑
    const Dispatch = async(task={})=>{
        const TASKNOTIFYCMD = 7;//任务通知
        if (!task || task.opcmd != TASKNOTIFYCMD 
            || !task.link || !task.link.startsWith("http")) {
            return ;//地址没有的情况
        }
        utilSrv.Write(utilSrv.INFO, "任务处理", task);
        if (task.priority && task.priority == 1) {
            await doTaskExec(task); //最高优先级
        } else {//强行入库，不然并发控制不住
            cacheSrv.Push(task);
        }
    };
    const JobMonitorStart = (config={})=>{
        let lstTime = -1; //初始化
        const taskCheckName = 'task-check-alarm';
        //根据设备设置，限制允许执行的最大并发任务数
        if (config && config.limit_tasks > 0) {
            utilSrv.maxJobTabs = config.limit_tasks;
        }
        const taskCheckFn = async()=>{//设置定时检测
            try {
                const nTime = (new Date()).getTime();
                if (lstTime != -1 && nTime - lstTime < 3000) {
                    return; //执行时间间隔小于8秒
                }
                lstTime = nTime;//记录最近一次执行时间
                cacheSrv.removeTabCache(); //清理旧记录
                const jobTabs = await chrome.tabs.query({});
                if (jobTabs && jobTabs.length >= utilSrv.maxJobTabs) {
                    return;//任务达到上限入库
                }
                let lstSize = await cacheSrv.Count();
                let nSize = utilSrv.maxJobTabs - jobTabs.length;
                utilSrv.Write(utilSrv.INFO, "任务检测开启任务数:", nSize, lstSize);
                if (nSize > 0) {//有剩余位置的情况执行
                    cacheSrv.Curor(nSize, doTaskExec);
                }
            } catch (err) {
                utilSrv.Write(utilSrv.INFO, "任务检测", err);
            }
        };
        taskCheckFn(); //启动的时候默认执行一次任务检测
        messageSrv.PushOcTimer(1, taskCheckFn);//10秒检测一次
        alarmSrv.doListener(taskCheckName, taskCheckFn);
    };
    const WsMonitorStart = (config={})=>{
        const alarmWsName = 'ws-heartbeat-alarm';
        alarmSrv.doListener(alarmWsName, async()=>{
            utilSrv.Write(utilSrv.INFO, "心跳检测", backgroundApp.wsSrv);
            if (backgroundApp.wsSrv.state() && backgroundApp.wsSrv._pingState < 3) {
                let waitTasks = await cacheSrv.Count();//已经连线的情况
                let seqno = utilSrv.uuid(), devWaitTask = waitTasks;
                if (backgroundApp.waitTask == waitTasks) {
                    devWaitTask = -1; //没有变动的话
                }
                backgroundApp.wsSrv._pingState += 1;
                backgroundApp.waitTask = waitTasks;//保存最近一次数量
                let jspack  = JSON.stringify({wait_tasks:devWaitTask});
                backgroundApp.wsSrv.sendPacket(5, seqno, jspack);
            } else {//重新联络，ping连续3次没有回调的话
                const deviceId = await utilSrv.DeviceId();
                backgroundApp.wsSrv = new SBimsc.websocks(config.ws, deviceId);
            }
        });
        messageSrv.PushOcTimer(1, async()=>{//检测任务
            if (!backgroundApp.wsSrv || !backgroundApp.wsSrv.state()) {
                const deviceId = await utilSrv.DeviceId();
                backgroundApp.wsSrv = new SBimsc.websocks(config.ws, deviceId);
            }
        });
    };
    const TabMonitorStart = ()=>{
        let lstTime = -1; //初始化
        const alarmTabName = "tab-timeout-alarm"
        const taskCheckFn = async()=>{
            const nTime = (new Date()).getTime();
            if (lstTime != -1 && nTime - lstTime < 8000) {
                return; //执行时间间隔小于8秒
            }
            lstTime = nTime;//记录最近一次执行时间
            let tabs = []; //过滤结果
            for (let i=0; i < alarmSrv.tabs.length; i++) {
                const item = alarmSrv.tabs[i];
                try {//拦截异常
                    const tab = await chrome.tabs.get(item.tabId);
                    utilSrv.Write(utilSrv.INFO, "监控tab", item, tab);
                    if (!tab || item._ - nTime < 1000) {
                        if (tab) {//被动超时关闭
                            await chrome.tabs.remove(tab.id);
                        }
                        continue;
                    }
                    tabs.push(item); //放回去继续监控 
                } catch (err) {
                    continue;
                }
            }
            alarmSrv.tabs = tabs;
        };
        messageSrv.PushOcTimer(2, taskCheckFn);
        alarmSrv.init(); //完成一下初始化
        alarmSrv.doListener(alarmTabName, taskCheckFn);
    };
    //初始化消息监听的业务处理逻辑
    backgroundApp.init = async() => {
        messageSrv.doListenMessageDispatch(); //消息监听
        TabMonitorStart(); //打开的tab数量监控，检测自动关闭
    };
    //完成基础数据初始化逻辑
    const initData = async(config) => {
        if (config && config.video && config.video.items) {
            config.video.items.forEach(async(item) => {
                if (item.domain && item.value) {
                    const sKey = 'v_domain_'+item.domain;
                    const eData= await chrome.storage.local.get([sKey]);
                    if (!eData || !eData[sKey]) {//不存在则设置
                        chrome.storage.local.set({[sKey]:item.value});
                    }
                }
            });
        }
    };
    //启动服务监听,维持心跳,断开重连等等
    backgroundApp.run = async(config={})=> {
        try {
            let deviceId = await utilSrv.DeviceId();
            JobMonitorStart(config);//任务队列监控
            if (deviceId && config.ws && config.is_down == 1) {//开启ws服务的情况
                backgroundApp.wsSrv = new SBimsc.websocks(config.ws, deviceId);
                SBimsc.sethooks("onmessage", Dispatch);
                WsMonitorStart(config);//开启websocket服务监控
            }
        } catch(err) {
            utilSrv.Write(utilSrv.ERROR, "ws服务异常", err);
        }
    };
    //启动执行APP服务
    backgroundApp.startApp = async () => {
        try {
            const config = await apiCore.Register();
            if (!config) {//失败的情况启动服务
                return false;
            }
            backgroundApp.run(config);
            const store = new UseChromeStore();
            store.Set("_config_", config);
            config && initData(config); //完成数据初始化
            return true;
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "服务启动注册失败", err);
        }
        return false;
    };

    return backgroundApp;
})();
