import pako from "../../lib/pako"
import Base64 from "../../lib/base64"
import ByteBuffer from "../../lib/byte-buffer"
export default (function(){
    let hashLen=2;
    const compress=(datbuf)=>{
        try {
            let deflate = new pako.Deflate();
            deflate.push(datbuf.raw, true);
            if (deflate.err) {//数据解压出来失败的业务逻辑
                throw {code: 503, msg: "compress error:"+deflate.err+"!"};
            }
            datbuf = new ByteBuffer(deflate.result);
        } catch(err) {
            throw {code: 503, msg: "compress error:"+err.toString()+"!"};
        }
        return datbuf;
    };

    const uncompress=(datbuf)=>{
        try {
            let inflate = new pako.Inflate();
            inflate.push(datbuf.raw, true);
            if (inflate.err) {
                throw {code: 503, msg: "uncompress error:"+inflate.err+"!"};
            }
            datbuf = new ByteBuffer(inflate.result);
        } catch(err) {
            throw {code: 503, msg: "uncompress error:"+err.toString()+"!"};
        }
        return datbuf;
    };
    const _crypt=(datbuf, keys)=> {
        let buffer = new ByteBuffer(datbuf.length);
        let keybuf = new ByteBuffer(keys.length * 3);
        let j = 0, mbyte = 0, klen = keybuf.writeString(keys);
        datbuf.index = 0; keybuf.index = 0; buffer.index = 0;
        for (let idx = 0; idx < datbuf.length; idx++) {
            mbyte = datbuf.readUnsignedByte();
            if (idx % hashLen == 0) {//偶数位做计算处理
                keybuf.index = j % klen;
                mbyte  = mbyte ^ keybuf.readUnsignedByte();
                j++;
            }
            buffer.writeUnsignedByte(mbyte);
        }
        return buffer;
    };
    return {
        gen:()=>{
            let d = new Date();
            return d.getTime().toString();
        },
        comString:(str='')=>{
            let datbuf = new ByteBuffer(str.length * 3);
            let nsize  = datbuf.writeString(str);
            datbuf = datbuf.slice(0, nsize);
            datbuf = compress(datbuf);//先做数据压缩
            return nsize + '$' + Base64.fromUint8Array(datbuf.raw);
        },
        encrypt:(str, keys = '')=>{
            let datbuf = new ByteBuffer(str.length * 3);
            let nsize  = datbuf.writeString(str);
            datbuf = datbuf.slice(0, nsize);
            datbuf = compress(datbuf);//先做数据压缩
            let buffer = _crypt(datbuf, keys);
            return nsize+'$'+Base64.fromUint8Array(buffer.raw);
        },
        decrypt:(str, keys = '')=>{
            let [nsize, ostr] = str.split("$", 2);
            let oribuf= Base64.toUint8Array(ostr);
            let datbuf= new ByteBuffer(oribuf);
            let buffer= _crypt(datbuf, keys);
            buffer = uncompress(buffer);//最后数据解压
            buffer.index = 0;
            str = buffer.readString(nsize);
            return str;
        }
    };
})();