import utilSrv from "./utils";

//异步获取cookie的逻辑
const getAllCookies = (domainStr, cookieItems, cookieMap)=> {
  return new Promise((resolve, reject) => {
    chrome.cookies.getAll({ domain:domainStr }, (cookies) => {
      if (chrome.runtime.lastError) {
        reject(chrome.runtime.lastError);
      } else {//成功的情况逻辑
        for (let i = 0; i < cookies.length; i++) {
          const cookie = cookies[i];
          if (!cookieMap[cookie.name]) {
            cookieMap[cookie.name] = true;
            cookieItems.push(cookie.name+'='+cookie.value);
          }
        }
        resolve(cookieItems)
      }
    });
  });
};

//通过bgscript加载脚本
export const loadCookie = async (rawDomain, rawCookies) => {//获取cookie
  const domains = rawDomain.split('.');
  const cookieItems = [];
  const cookieMap = {}; //获取日志
  const nSubDomain = domains.length - 2;
  for (let i = 0; i <= nSubDomain; i++) {
    const domainStr = domains.slice(i).join('.');
    await getAllCookies(domainStr, cookieItems, cookieMap);
  }
  if (rawCookies) {//附加上客户端提交上来的document.cookie
    let mCookie = rawCookies.split(";");
    for (let i = 0; i < mCookie.length; i++) {
      const cookieStr = mCookie[i];
      const items = cookieStr.split("=");
      if (items.length == 2 && !cookieMap[items[0]]) {
        cookieItems.push(cookieStr.trim());
      }
    }
  }
  utilSrv.Write(utilSrv.INFO, "获取Cookie", cookieItems);
  return cookieItems;
};