import utilSrv from "./utils"
import Crypt from "./crypt"
var SBimsc = {socks:null, hooks:{}};
SBimsc.sethooks = function(skey, cb) {//定义事件回到机制
    SBimsc.hooks[skey] = cb;
};
SBimsc.debug = function() {
    utilSrv.Write(utilSrv.INFO, ...arguments)
};
SBimsc.coString = function (data) {
    (!data) && (data = 0);
    if (data.constructor !== String) {
        return (new Number(data)).toString();
    }
    return data;
};

SBimsc.sethooks("error", SBimsc.debug);
SBimsc.sethooks("cbchat", SBimsc.debug);
SBimsc.sethooks("onclose", SBimsc.debug);
SBimsc.sethooks("onmessage", SBimsc.debug);
SBimsc.websocks = function(uri, deviceId) {
    var self    = this;
    (SBimsc.socks) && SBimsc.socks.close();
    self._uri       = uri;
    self._deviceId  = deviceId;
    self._conned    = false;
    self._pingState = 0; //ping统计
    self._mqueue    = {};
    try {
        SBimsc.socks    = new WebSocket(uri);
        SBimsc.socks.onmessage = function(evt) {
            self.onmessage(evt);
        };
        SBimsc.socks.onclose = function(evt) {
            self.onclose(evt);
        };
        SBimsc.socks.onopen = function(evt) {
            self.onopen(evt);
        };    
    } catch (err) {
        utilSrv.Write(utilSrv.ERROR, "通信服务:", err);
    }
};

//执行业务对象实例
SBimsc.websocks.prototype = {
    constructor:SBimsc.websocks,
    doConnect: function() {
        var self  = this;
        var seqno = utilSrv.uuid();
        var jspack= {device_id:self._deviceId};
        jspack  = JSON.stringify(jspack);
        self.sendPacket(6, seqno, jspack);
    },
    cbproc: function(data) {//处理消息业务逻辑
        var self = this;
        self._pingState = 0;
        if(data.opcmd == 6) {//登录成功的回调
            self._conned = (data.code == 0)? true:false;
        } else {//发送消息回调
            if(data.code == 0 && !!SBimsc.hooks.cbchat && self._mqueue[data.seqno]) {
                SBimsc.hooks.cbchat(data, self._mqueue[data.seqno]);
                delete self._mqueue[data.seqno];
            }
        }
    },
    state: function() {
        return this._conned;
    },
    onopen: function(evt) {
        var self= this;
        SBimsc.debug(evt, "websockets connected.");
        self.doConnect();
    },
    onclose: function(evt) {
        var self = this;
        self._conned = false;
        SBimsc.debug(evt, "websockets closed.");
        if (SBimsc.hooks.onclose) {//服务端关闭
            SBimsc.hooks.onclose();
        }
    },
    onmessage: function(evt) {
        var self = this;
        try {
            var json = evt.data;
            json = JSON.parse(json);
            if(json) {
                self.cbproc(json);
                SBimsc.hooks.onmessage(json);
            }
            SBimsc.debug("websockets onmessage.", evt);
        } catch(err) {
            SBimsc.debug(err);
        }
    },
    sendPacket: function(apcode, seqno, json) {
        var data  = {'opcmd':apcode, 'seqno':seqno, 'packet':json};
        data = JSON.stringify(data);
        data = Crypt.comString(data);
        if (SBimsc.socks) {
            try {
                SBimsc.socks.send(data);
            } catch (err) {//异常的逻辑
                utilSrv.Write(utilSrv.ERROR, "ws发送失败", err)
            }
        };
    }
};
export default SBimsc;