import Crypt from "./crypt"
import utilSrv from "./utils"
const xToken = 'x.tk';
const xUser  = 'x.user';

//清理登录token
export const xClearLogin = async() => {
    await chrome.storage.local.remove([xToken, xUser]);
}

//初始化业务逻辑
export const xInitLogin = async() => {
    const sign = await chrome.storage.local.get([xToken]);
    const s = await chrome.storage.local.get([xUser]);
    const data = (!s[xUser])? null:JSON.parse(s[xUser]);
    if (data && sign && sign[xToken]) {
        data.sign = sign[xToken];
    }
    return data;
}

//设置登录逻辑
export const xSetLogin = async(data) => {
    await chrome.storage.local.set({ 
        [xToken]: data.sign
    });
    delete data.sign;//删除避免重复存储
    await chrome.storage.local.set({ 
        [xUser]: JSON.stringify(data)
    });
}

//判定是否登录的逻辑
export const xIsLogin = async () => {
    const xTk = await chrome.storage.local.get([xToken]);
    if (xTk && xTk[xToken]) {//存在的情况
        return true;
    }
    return false;
}

//发送http请求的逻辑
export const APIRequest = async(url = '',  method = 'GET', params = {})=>{
    method = method.toUpperCase();
    if (!url.startsWith("http")) {
        url = utilSrv.api + url;
    }
    if (method == 'GET') {
        let queryValues = []; //数据拼接字符串
        Object.keys(params).forEach(key => {
            queryValues.push(key + '=' + encodeURIComponent(params[key]));
        });
        if (queryValues && queryValues.length > 0) {
            url = url + '?' + queryValues.join("&");
        }
    }
    const hashKey = Crypt.gen();  
    let reqConfig = {//请求的参数配置
        credentials: 'include',
        method: method,
        headers: {//交互的数据格式
            'Accept': '*/*', 
            'x-key': hashKey,
            'Content-Type': 'plain/text'
        }
    }
    const xTk = await chrome.storage.local.get([xToken]);
    if (xTk && xTk[xToken]) {//存在的情况-登录的令牌
        reqConfig.headers.signature = xTk[xToken];
    }
    //await antiReqHeader(reqConfig);
    if (method == 'POST') {//post json数据请求
        (!params) && (params={});
        params._ = (new Date()).getTime();
        const body = JSON.stringify(params);
        Object.defineProperty(reqConfig, 'body', {
            value: Crypt.encrypt(body, hashKey)
        })
    }
    try {//拦截异常的处理逻辑
        utilSrv.Write(utilSrv.INFO, "网络请求:", url, reqConfig, params);
        const response = await fetch(url, reqConfig); 
        //antiRspHeader(response);//设置请求
        if (response.status == 403) {
            return;
        }
        let result =  await response.text();
        utilSrv.Write(utilSrv.INFO, "请求结果:", result);
        result = Crypt.decrypt(result, hashKey);
        utilSrv.Write(utilSrv.INFO, "请解码结果:", result);
        const data = JSON.parse(result);
        if (data && (data.code === 9999 || data.code === 9998)) {
            xClearLogin();//退出逻辑
        }
        return data;
    } catch (err) {
        utilSrv.Write(utilSrv.ERROR, "网络请求异常", url, err)
        throw new Error(err)
    }
};
