import utilSrv from "./utils"
import { APIRequest } from "./request"

export default (function(){
    var apiCore = {};//封装API的所有请求
    apiCore.Register = async ()=>{//设备注册
        try {
            let deviceId = await utilSrv.DeviceId();
            const fpData = await chrome.storage.local.get(['_fp']);
            const params = {device:"-", device_id:deviceId,
                fingerprint:fpData && fpData._fp? fpData._fp:'-'};
            let result = await APIRequest("/rp-device-register", "POST", params);
            if (result && result.code == 0) {//成功的情况,将配置的视频地址提前注入
                return result.data;
            }
            return null;
        } catch (errS) {
            utilSrv.Write(utilSrv.INFO, "注册设备失败:", errS);
        }
        return null;
    };

    //获取执行模版的情况逻辑
    apiCore.GetScript = async (uuid='', from='x.tools')=>{//获取匹配的脚本
        let sUrl = "/rp-market-exec";
        if (from != 'x.tools') {//脚本
            sUrl = "/rp-get-script";
        }
        let result = await APIRequest(sUrl, "POST", {uuid:uuid});
        if (result && result.code == 0) {//成功的情况
            return result.data;
        }
        return null;
    };

    apiCore.GetTemplate = async (uuid='')=>{//获取匹配的模板
        let result = await APIRequest("/rp-get-template", "POST", {uuid:uuid});
        if (result && result.code == 0) {//成功的情况
            return result.data;
        }
        return null;
    };

    //任务执行回调业务处理逻辑data:{execute_id,data}, api地址
    apiCore.SetCallback = async (params={}, apiURL="/rp-cb-execute")=>{
        if (apiURL && apiURL.startsWith("http")) {
            return await utilSrv.JsonRequest(apiURL, "POST", params);
        } else {//内部系统的回调逻辑
            (!apiURL) && (apiURL = "/rp-cb-execute");
            const deviceId = await utilSrv.DeviceId();
            params.device_id = deviceId;//绑定设备
            let result = await APIRequest(apiURL, "POST", params);
            if (result && result.code == 0) {//成功的情况
                return result.data;
            }
        }
        return null;
    };

    //绑定到账号的处理逻辑device_id,account,device
    apiCore.SetCookie = async (params={})=>{
        let result = await APIRequest("/rp-cb-cookie", "POST", params);
        if (result && result.code == 0) {//成功的情况
            return result.data;
        }
        return null;
    };
    return apiCore;
})();
