export default (function(){
    const timeOutLimit = 60*1000 //最长允许执行一小时
    var alarmSrv = {hanle:{}, tabs:[]};
    alarmSrv.init = () => {//初始化逻辑
        chrome.alarms.onAlarm.addListener((evt) =>{
            if (!alarmSrv.hanle[evt.name]) {
                return;//未注册监听的情况
            }
            //执行监听注册的事件
            alarmSrv.hanle[evt.name]();
        });
    };
    //创建，并注册到监听逻辑
    alarmSrv.doListener=(name="alarm", fn=()=>{}) =>{
        alarmSrv.hanle[name] = fn;//注册回调
        chrome.alarms.create(name, {
            delayInMinutes: 1,
            periodInMinutes: 1,
        });
    };
    alarmSrv.tagRegister = (tabId="", timeout=0) =>{//超时监控逻辑
        let sTime = (new Date()).getTime();
        if (timeout && timeout > 0) {//转换毫秒
            sTime += timeout*1000;
        } else {
            sTime += timeOutLimit;
        }
        alarmSrv.tabs.push({tabId:tabId, _:sTime});
    };
    return alarmSrv; 
})();