
import utilSrv from "../base/utils"
import { connection } from "./idb-conn";
import { tbComments } from "./idb-schema";
export class CommentsSrv {
    constructor() {
        this.tableName = tbComments.name;
    }

    //全部清空的逻辑
    async clear(url) {
        let options = {
            from: this.tableName
        };
        if (url) {//删除指定的域名下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where = { domain:domain};
        }
        await connection.remove(options);
    }

    //直接删除记录
    async remove(sn) {
        await connection.remove({
            from: this.tableName,
            where: {
                sn: sn
            }
        });
    }

    //推送记录数据资料信息
    async Push(params={sn:'', url:'', meta:{}}) {
        if (!params || !params.sn || !params.url) {
            utilSrv.Write(utilSrv.ERROR, "入库参数异常", params);
            return;
        }
        const { sn, url, meta } = params;
        const domain = await utilSrv.Sdomain(url);
        const data = { meta:meta, domain:domain, 
            sn:sn, created_at: (new Date()).getTime()};
        try {
            const iData = await connection.select({
                from: this.tableName,
                where: { sn: sn, domain: domain }
            });
            if (iData && iData.length > 0) {
                await connection.update({
                    in: this.tableName,
                    set: data,
                    where: { sn: sn, domain: domain }
                });
            } else {
                await connection.insert({
                    into: this.tableName,
                    values: [data],
                    return: true
                });
            }
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "评论入库异常", err);
        }
    }

    //获取记录数量
    async Count(url='') {
        const options = {
            from: this.tableName,
            where: {},
        };
        if (url) {//获取这个界面下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where.domain = domain;
        }
        return await connection.count(options);
    }

    //任务查询遍历的逻辑
    async GetList(pageNum=1, pageSize=50, url=''){
        const options = {
            from: this.tableName,
            limit: pageSize,
            skip: (pageNum - 1) * pageSize,
            where: {},
            order: {by: 'created_at', type: 'desc'}
        };
        if (url) {//获取这个界面下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where.domain = domain;
        }
        const list = await connection.select(options);
        return list
    }

    //任务查询遍历的逻辑
    async Curor(limit=1, url='', fn=(item={})=>{return;}){
        const options = {
            from: this.tableName,
            limit: limit,
            where: {},
            order: {by: 'created_at', type: 'asc'}
        };
        if (url) {//获取这个界面下的数据
            if (url.startsWith('http')) {
                url = await utilSrv.Sdomain(url);
            }
            options.where.domain = url;
        }
        const list = await connection.select(options);
        if (list && list.length > 0) {//执行待处理的任务
            list.forEach((item)=>{
                fn(item);
            });
        }
    }
}