import md5 from 'blueimp-md5';
import utilSrv from "../base/utils"
import { connection } from "./idb-conn";
import { tbMedia, MediaRefType } from "./idb-schema";
export class MediaSrv {
    constructor() {
        this.tableName = tbMedia.name;
    }

    //全部清空的逻辑
    async clear(url, refType) {
        let options = {
            from: this.tableName
        };
        if (refType) {//清空指定类被数据
            options.where = {ref_type:refType};
        }
        if (url) {//删除指定的域名下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where = { domain:domain};
        }
        await connection.remove(options);
    }

    //直接删除记录
    async remove(id) {
        await connection.remove({
            from: this.tableName,
            where: {
                id: id
            }
        });
    }

    //推送记录数据资料信息
    async Push(url, status, refType=MediaRefType.image, items=[]) {
        let prefix = 'd@', sKey = '', vDomain  = null;
        const domain = await utilSrv.Sdomain(url);
        if (refType == MediaRefType.image) {
            prefix = 'i@';
        } else if (refType == MediaRefType.video) {
            prefix = 'v@';
            sKey   = await utilSrv.Vdomain(url);
            if (sKey && sKey.length > 0) {//视频没有配置地址过滤
            const vcDomain = await chrome.storage.local.get(sKey);
                let vDStr = vcDomain[sKey] || '';
                vDStr = vDStr.replace(/[;；，\s]+/g, ',');
                if (vDStr && vDStr.length > 0) {
                    vDomain = vDStr.split(',');
                }
            }
        }
        const urlHash= md5(url);
        for (let idx = 0; idx < items.length; idx++) {
            const meta = items[idx];
            if (!meta || !meta.src) {
                continue
            }
            if (vDomain && vDomain.length > 0) {
                const isOk = vDomain.some((item)=>meta.src.includes(item))
                if (!isOk) {//不匹配被过滤了
                    continue;
                }
            }
            const md5Str = prefix + urlHash +':'+md5(meta.src);
            const data = {meta:meta, domain:domain, ref_type:refType,
                md5str:md5Str, status:status, created_at: (new Date()).getTime()};

            try {
                const iData = await connection.select({
                    from: this.tableName,
                    where: { md5str: md5Str }
                });
                if (iData && iData.length > 0) {
                    await connection.update({
                        in: this.tableName,
                        set: data,
                        where: { md5str: md5Str }
                    });
                } else {
                    await connection.insert({
                        into: this.tableName,
                        values: [data],
                        return: true
                    });
                }
            } catch (err) {
                utilSrv.Write(utilSrv.ERROR, "视频入库异常", err);
            }
        } 
    }

    //获取记录数量
    async Count(refType, url='') {
        const options = {
            from: this.tableName,
            where: {ref_type: refType},
        };
        if (url) {//获取这个界面下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where.domain = domain;
            /*
            let prefix = 'd@';
            if (refType == MediaRefType.image) {
                prefix = 'i@';
            } else if (refType == MediaRefType.video) {
                prefix = 'v@';
            }
            const md5Str = prefix + md5(url);
            options.where.md5str = {like: md5Str+'%'};
            */
        }
        return await connection.count(options);
    }

    //任务查询遍历的逻辑
    async GetList(pageNum=1, pageSize=50, refType=MediaRefType.image, url=''){
        const options = {
            from: this.tableName,
            limit: pageSize,
            skip: (pageNum - 1) * pageSize,
            where: {ref_type:refType},
            order: {by: 'created_at', type: 'desc'}
        };
        if (url) {//获取这个界面下的数据
            const domain = await utilSrv.Sdomain(url);
            options.where.domain = domain;
            /*
            let prefix = 'd@';
            if (refType == MediaRefType.image) {
                prefix = 'i@';
            } else if (refType == MediaRefType.video) {
                prefix = 'v@';
            }
            const md5Str = prefix + md5(url);
            options.where.md5str = {like: md5Str+'%'};
            */
        }
        const list = await connection.select(options);
        return list
    }
}