import utilSrv from "@/static/js/base/utils"
import messageSrv from '@/static/js/base/m-sender';
import {FFmpegDownloadUI} from "@/static/js/base/ui-ffmpeg"

//backgroud-script的业务处理逻辑
export const initMessagePort = () => {
    let contentPort = null;
   
    //初始化创建消息port管道
    const init = async(sender) => {
        const clients = await self.clients.matchAll({
            includeUncontrolled: true,
            type: 'window'
        });
        const offscreenClient = clients.find(c => c.url.includes('offscreen.html'));
        if (!offscreenClient) {//抛出异常
            throw Error('Offscreen不存在');
        }
        utilSrv.Write(utilSrv.INFO, 'port-BG初始化开启');
        const channel = new MessageChannel();
        contentPort   = channel.port2;// 暂存 port2
        const ocPort  = channel.port1;
        // 把 ocPort 交给 Offscreen
        offscreenClient.postMessage({ type: utilSrv.msgTypeACCEPTPORT }, [ocPort]);
        // 注入 bridge iframe 到页面
        await chrome.scripting.executeScript({
            target: { tabId: sender.tab.id },
            func: () => {
                const iframe = document.createElement('iframe');
                iframe.src = chrome.runtime.getURL('template/bridge.html');
                iframe.style.display = 'none';
                iframe.id  = 'my-bridge-iframe';
                document.body.appendChild(iframe);
            }
        });
        utilSrv.Write(utilSrv.INFO, 'port-BG初始化完成');
    };

    // 找到 bridge iframe 的 client BRIDGE_READY
    const ready = async() => {
        if (!contentPort) {
            return;
        }
        utilSrv.Write(utilSrv.INFO, 'port-Bridge就绪');
        const clients = await self.clients.matchAll({
            includeUncontrolled: true,
            type: 'window'
        });
        // 找到 bridge.html 的 client
        const bridgeClient = clients.find(c => c.url.includes('bridge.html'));
        if (bridgeClient) {
            bridgeClient.postMessage({ type: utilSrv.msgTypePORTDELIVERY }, [contentPort]);
            utilSrv.Write(utilSrv.INFO, 'port-Bridge端口投递');
            contentPort = null;
        }
    }
    return {init, ready};
}

//content-script脚本逻辑
export const contentFFmpeg = () => {
    let workerPort = null;
    let workData   = null;
    const ffmpegUI = new FFmpegDownloadUI();
    const closeWorkPort = () => {
        if (workerPort) {
            workerPort.close();
            workerPort = null;
            utilSrv.Write(utilSrv.INFO, 'port-content端口释放');
        }
        setTimeout(()=>{
            ffmpegUI.hide();
        }, 3000);
    }

    // 接收来自 offscreen 的消息（可选，用于进度反馈）
    const onWorkerMessage = (event) => {
        if (event.data.type === 'PROGRESS') {
            ffmpegUI.updateStatus('正在合并音视频...');
            ffmpegUI.updateProgress(80);
            utilSrv.Write(utilSrv.INFO, 'port-content执行媒体合并');
        } else if (event.data.type === 'FINISH') {
            ffmpegUI.updateStatus('完成合并音视频...');
            ffmpegUI.updateProgress(95);
        } else if (event.data.type === 'DONE') {
            utilSrv.Write(utilSrv.INFO, 'port-content执行媒体完成');
            ffmpegUI.updateProgress(100);
            closeWorkPort(); //释放资源
        } else if (event.data.type === 'ERROR') {
            utilSrv.Write(utilSrv.INFO, 'port-content资源ffmpeg处理失败');
            ffmpegUI.updateStatus('音/视合并ffmpeg处理失败');
            closeWorkPort(); //释放资源
        }
    };

    const evtListener = (event) => {
        if (event.data?.type === utilSrv.msgTypeBRIDGEPORT && event.ports[0]) {
            workerPort = event.ports[0];
            workerPort.onmessage = onWorkerMessage;
            utilSrv.Write(utilSrv.INFO, 'port-content端口就绪');
            const iframe = document.getElementById('my-bridge-iframe');
            if (iframe) iframe.remove();
            startSendingData();// port 就绪，开始发送数据
        }
    };

    //解析m3u8-mp4格式的地址
    const parseM3u8 = (text, baseUrl) => {
        const lines = text.split(/\r?\n/);
        const resources = [];
        let isEncrypted = false; //是否加密
        let pendingMap = null; // 遇到 EXT-X-MAP 时暂存，下一个媒体分片前插入
        const absUrl = (u) => (u.startsWith('http') ? u : baseUrl + u);
        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (!line) continue;

            if (line.startsWith('#EXT-X-MAP:')) {
                const uriMatch = line.match(/URI="([^"]+)"/);
                if (uriMatch) {//解码地址
                    const myUrl = absUrl(uriMatch[1]);
                    pendingMap= myUrl;
                }
            } else if (line.startsWith('#EXT-X-KEY:')) {
                if (line.includes('METHOD=SAMPLE-AES') || line.includes('METHOD=AES-128')) {
                    isEncrypted = true; 
                } else if (line.includes('METHOD=NONE')) {
                    isEncrypted = false;
                }
            } else if (line.startsWith('#EXTINF')) {
                // 下一个非注释行是媒体分片 URL
                let j = i + 1;
                while (j < lines.length && (lines[j].trim() === '' || lines[j].trim().startsWith('#'))) j++;
                if (j < lines.length) {
                    if (pendingMap) {// 先插入 pending init
                        resources.push({ kind: 'init', isEncrypted: false, url: pendingMap });
                        pendingMap = null;
                    }
                    const myUrl = absUrl(lines[j].trim());
                    resources.push({ kind: 'media', isEncrypted, url: myUrl });
                    i = j; // 跳过已处理的 URL 行
                }
            }
        }
        return resources;
    };

    //下载m3u8视频格式
    const downloadM3u8 = async(data) => {
        const m3u8Url = data.m3u8; //地址
        utilSrv.Write(utilSrv.INFO, "m3u8地址", data.m3u8);
        const baseUrl = m3u8Url.substring(0, m3u8Url.lastIndexOf('/') + 1);
        const myFetch= window.oFetch || window.fetch;
        const text   = await (await myFetch(m3u8Url)).text();
        const source = {buffers:[], type:'ts'};
        if (text.includes('#EXT-X-MAP') && text.includes('.mp4')) {
            source.type = 'mp4';
            const resources = parseM3u8(text, baseUrl);
            const count = resources.filter(x => x.isEncrypted).length;
            if (count > 0) {//遇到加密的情况逻辑
                throw Error(`数据分片已被加密,无法处理...`);
            }
            for (let i = 0; i < resources.length; i++) {
                const r = resources[i];
                if (r.isEncrypted) {// 实际应用中，你可能需要一个占位符或者直接中断
                    utilSrv.Write(utilSrv.DEBUG, `[跳过] 遇到加密分片 (SAMPLE-AES)，前端无法处理: ${r.url}`);
                    continue; 
                }
                const data = await myFetch(r.url);
                if (!data.ok) {//加载失败的情况
                    utilSrv.Write(utilSrv.DEBUG, `资源下载失败 ${r.url} HTTP ${data.status}`);
                    throw(new Error(`资源下载失败 ${r.url} HTTP ${data.status}`));
                }
                const buffer = await data.arrayBuffer();
                source.buffers.push(buffer); //下载ts分片
                const ratio = parseInt(((i+1) / resources.length)*45);
                ffmpegUI.updateProgress(30+ratio);
            }
            utilSrv.Write(utilSrv.INFO, `累计下载${resources.length}个分片...`);
            ffmpegUI.updateStatus(`累计下载${resources.length}个分片...`);
        } else {//普通的ts下载
            source.type = 'ts';
            const segments = text.split('\n')
                .filter(line => line.trim() && !line.startsWith('#'))
                .map(line => line.startsWith('http') ? line : baseUrl + line);
            for (let i = 0; i < segments.length; i++) {
                const buffer = await (await myFetch(segments[i])).arrayBuffer();
                source.buffers.push(buffer); //下载ts分片
                const ratio = parseInt(((i+1) / segments.length)*45);
                ffmpegUI.updateProgress(30+ratio);
            }
            utilSrv.Write(utilSrv.INFO, `累计下载${segments.length}个分片...`);
            ffmpegUI.updateStatus(`累计下载${segments.length}个分片...`);
        }
        return source;
    };

    // 这里完成下载之后转发到后端执行数据合并逻辑
    const downloadMerge = async (data) => {
        utilSrv.Write(utilSrv.INFO, 'port-content媒体下载', data);
        const source = {'video':null, 'audio':null};
        const myFetch= window.oFetch || window.fetch;
        for (let i = 0; i < data.video.length; i++) {
            const videoUrl = data.video[i];
            try {
                const videoRes = await myFetch(videoUrl);
                if (!videoRes.ok) { // 403、404 等都会走到这里
                    utilSrv.Write(utilSrv.INFO, `视频下载失败: HTTP ${videoRes.status}`, videoUrl);
                    continue; // 换下一个 URL 重试
                }
                source.video = await videoRes.arrayBuffer();
                break
            } catch (err) {
                utilSrv.Write(utilSrv.INFO, "视频下载失败", err);
            }
        }
        for (let i = 0; i < data.audio.length; i++) {
            const audioUrl = data.audio[i];
            try {
                const audioRes = await myFetch(audioUrl);
                if (!audioRes.ok) { // 403、404 等都会走到这里
                    utilSrv.Write(utilSrv.INFO, `音频下载失败: HTTP ${audioRes.status}`, audioUrl);
                    continue; // 换下一个 URL 重试
                }
                source.audio = await audioRes.arrayBuffer();
                break
            } catch (err) {
                utilSrv.Write(utilSrv.INFO, "音频下载失败", err);
            }
        }
        if (!source.video || !source.audio) {
            throw Error('音频或者视频不完整,无法下载');
        }
        utilSrv.Write(utilSrv.INFO, "port-content视频/音频下载完成");
        return source;
    };

    // 开始发送数据
    const startSendingData = async () => {
        if (!workerPort) return;
        try {
            if (workData.video && workData.audio) {//合并的逻辑
                ffmpegUI.updateStatus('正在下载音/视频流...');
                const source = await downloadMerge(workData);
                ffmpegUI.updateProgress(30);
                //使用 Transferable 转移 ArrayBuffer 的所有权，零拷贝
                workerPort?.postMessage({
                    type: utilSrv.msgTypeMEDIADATA,
                    op: 'merge',
                    title: workData.title,
                    video: source.video,
                    audio: source.audio
                }, [source.video, source.audio]);
                ffmpegUI.updateProgress(55);
                utilSrv.Write(utilSrv.INFO, "port-content媒体转发完成");
            } else if (workData.m3u8 && workData.m3u8.startsWith('http')) {
                ffmpegUI.updateStatus('正在下载视频分片...');
                const source = await downloadM3u8(workData);
                //使用 Transferable 转移 ArrayBuffer 的所有权，零拷贝
                workerPort?.postMessage({
                    type: utilSrv.msgTypeMEDIADATA,
                    op: source.type,
                    title: workData.title,
                    segments: source.buffers,
                }, source.buffers);
                ffmpegUI.updateProgress(75);
                utilSrv.Write(utilSrv.INFO, "port-content媒体转发完成");
            } else {//还未做适配的情况
                workerPort?.postMessage({ type: 'ERROR', error: '当前格式还未适配' });
                return;
            }
        } catch (err) {
            utilSrv.Write(utilSrv.INFO, "port-content媒体处理失败", err);
            const mStatus = (err && err.message)? err.message:'音/视下载业务失败,🉑刷新重试';
            ffmpegUI.updateStatus(mStatus); //状态更新的
            workerPort?.postMessage({ type: 'ERROR', error: err.message });
            setTimeout(()=>{
                closeWorkPort(); //释放资源
            }, 500);
        }
    }

    //初始化发送下载导出指令
    const init = async (data) => {
        workData = data; //带执行的数据
        ffmpegUI.init();
        ffmpegUI.updateStatus('初始化下载环境...');
        utilSrv.Write(utilSrv.INFO, 'port-content启动');
        window.removeEventListener('message', evtListener);
        window.addEventListener('message', evtListener);
        await messageSrv.doSendMessage({ type: utilSrv.msgTypeSTARTMERGE });
        ffmpegUI.updateProgress(5);
    };
    return {init};
}