import utilSrv from "./utils"
let creatingOffscreen;
const Net_Rule_Id = 1001;
//心跳的初始化业务处理逻辑
export const ocHeartBeat = async()=>{//自动的时候载入
    const ocUrl = chrome.runtime.getURL("template/offscreen.html");
    const existingContexts = await chrome.runtime.getContexts({
        contextTypes: ['OFFSCREEN_DOCUMENT'],
        documentUrls: [ocUrl]
    });
    if (existingContexts.length > 0) return;
    if (creatingOffscreen) {
        await creatingOffscreen;
    } else {
        creatingOffscreen = chrome.offscreen.createDocument({
            url: ocUrl,
            reasons: [chrome.offscreen.Reason.USER_MEDIA],
            justification: '监控worker Service进入假死状态'
        });
        await creatingOffscreen;
        creatingOffscreen = null;
    }
};

//添加B站的请求头修正
const addRefererRule = async(referer) => {
    utilSrv.Write(utilSrv.INFO, "开启addRefererRule", referer);
    await chrome.declarativeNetRequest.updateSessionRules({
        removeRuleIds: [Net_Rule_Id],
        addRules: [{
            id: Net_Rule_Id,
            priority: 1,
            action: {
                type: 'modifyHeaders',
                requestHeaders: [
                    {
                        header: 'Referer',
                        operation: 'set',
                        value: referer,
                    }/*,
                    {
                        header: 'Origin',
                        operation: 'set',
                        value: 'https://www.bilibili.com'
                    }*/
                ]
            },
            condition: {
                requestDomains: ['bilivideo.com'],
                resourceTypes: ['xmlhttprequest'],
              //  initiatorDomains: [chrome.runtime.id]  // 只允许扩展自身发起
            }
        }]
    });

    const rules = await chrome.declarativeNetRequest.getSessionRules();
    console.log('当前规则:', JSON.stringify(rules, null, 2));
};

//删除请求头的业务处理逻辑
const removeRefererRule = async () => {
    utilSrv.Write(utilSrv.INFO, "关闭removeRefererRule");
    await chrome.declarativeNetRequest.updateSessionRules({
        removeRuleIds: [Net_Rule_Id]
    });
}

//规则的设定
export const doSetNetRolePolicy = async (link) => {
    if (link.includes('bilibili.com')) {
        await addRefererRule(link);
    } else {//清理掉规则
        await removeRefererRule();
    }
}

