import utilSrv from "../base/utils"
import { connection } from "./idb-conn";
import { tbCache, CacheRefType } from "./idb-schema";
export class CacheSrv {
    constructor() {
        this.tableName = tbCache.name;
    }
 
    //@return Object
    async TabCache(url) {
        const tabId = await this.tabId(url);
        if (tabId > 0) {//通过tab直接查询的情况
            const sKey = 'tab@'+String(tabId);
            const [data] = await connection.select({
                from: this.tableName,
                where: {
                    skey: sKey,
                    ref_type: CacheRefType.tab,
                }
            });
            //tab任务取完就删除
            if (data && data.meta) {
                this.removeCache(sKey);
                return data.meta;
            }
        }
        //通过URL再次查询一次
        const sKey = await utilSrv.Sdomain(url);
        const [data] = await connection.select({
            from: this.tableName,
            where: {
                skey: sKey,
                ref_type: CacheRefType.domain,
            }
        });
        return (!data || !data.meta)? null:data.meta;
    }

    //超过3分钟没获取自动删除
    async removeTabCache() {
        const createdAt = (new Date()).getTime() - 180*1000;
        await connection.remove({
            from: this.tableName,
            where: {
                ref_type: CacheRefType.tab,
                created_at: { '<': createdAt }
            }
        });
    }

    //全部清空的逻辑
    async DomainReset(url) {
        const sKey = await utilSrv.Sdomain(url);
        let options = {
            from: this.tableName,
            where: {
                skey: sKey,
                ref_type: CacheRefType.domain,
            }
        };
        await connection.remove(options);
    }

    //全部清空的逻辑
    async ClearCache(refType) {
        let options = {
            from: this.tableName
        };
        if (refType) {//清空指定类被数据
            options.where = {ref_type: refType};
        } 
        await connection.remove(options);
    }

    //tabId方式获取过直接删除
    async removeCache(sKey) {
        await connection.remove({
            from: this.tableName,
            where: {
                skey: sKey
            }
        });
    }

    //根据地址获取tabID
    async tabId(url) {
        const tabs = await chrome.tabs.query({ 
            url: url
        });
        if (tabs && tabs.length > 0) {
            return tabs[0].id;
        }
        return 0;
    }

    //@return number
    async SetTabCache(tabId, link, meta) {
        if (tabId > 0) {//保存记录
            const keyStr = 'tab@'+String(tabId);
            await this.SetCache(keyStr, CacheRefType.tab, meta);
        }
        const sKey = await utilSrv.Sdomain(link);
        await this.SetCache(sKey, CacheRefType.domain, meta);
    }

    //保存记录的逻辑
    async SetCache(sKey, refType, meta) {
        const sDate= new Date();
        const data = {skey:sKey, meta:meta, ref_type:refType, created_at: sDate.getTime()};
        return await connection.insert({
            into: this.tableName,
            values: [data],
            upsert: true, 
            return: true
        });
    }

    //存在的情况跳过，否则信息
    async SkipCache(sKey, refType, meta) {
        const [data] = await connection.select({
            from: this.tableName,
            where: {
                skey: sKey,
                ref_type: refType,
            }
        });
        if (data && data.meta) {//已经存在的情况跳过
            return;
        }
        this.SetCache(sKey, refType, meta)
    }

    async Push(data={}) {
        if (!data || data.id < 1) {//记录有问题的情况
            return;
        }
        const refType = CacheRefType.task;
        data.status = (data.priority && data.priority == 1)? 1:2;
        const sKey = 'task@'+String(data.id);
        const [row] = await this.SetCache(sKey, refType, data);
        if (!row) {//失败的情况逻辑
            utilSrv.Write(utilSrv.ERROR, "接收任务保存失败...");
        }
    }

     //db待处理任务数
    async Count() {
        const options = {
            from: this.tableName,
            where: {ref_type: CacheRefType.task},
        };
        return await connection.count(options);
    }
    
    //任务查询遍历的逻辑
    async Curor(limit=1, fn=(task={})=>{return 1;}){
        const options = {
            from: this.tableName,
            limit: limit,
            where: {ref_type:CacheRefType.task},
            order: {by: 'created_at', type: 'asc'}
        };
        const list = await connection.select(options);
        if (list && list.length > 0) {//执行待处理的任务
            list.forEach((item)=>{
                if (item && item.meta) {
                    fn(item.meta);
                }
                this.removeCache(item.skey);
            });
        }
    };

    //任务查询遍历的逻辑
    async GetList(limit=1, refType=CacheRefType.script){
        const options = {
            from: this.tableName,
            limit: limit,
            where: {ref_type:refType},
            order: {by: 'created_at', type: 'desc'}
        };
        const list = await connection.select(options);
        return list
    };
}