import utilSrv from "./js/base/utils"
import bgApp from "./js/bg_script/script"
import {ocHeartBeat} from "./js/base/worker"
import {initJsStore} from "./js/index-db/idb-service"
(async function(){
    utilSrv.Write(utilSrv.INFO, "bg script starting...", process.env.NODE_ENV, chrome);
    initJsStore(); //初始化数据库
    chrome.action.onClicked.addListener(async (tab) => {
        let url = (tab && tab.url)? tab.url:"";
        if (!url || !url.startsWith("http")) {
            return;
        }
        chrome.sidePanel.open({ tabId: tab.id });
    });
    await ocHeartBeat(); //开启服务心跳
    bgApp.init(); //初始化基础服务
    /** 安装完成自动连接 不需要登录的时候在连接了
    chrome.runtime.onMessage.addListener((message) => {
        utilSrv.Write(utilSrv.INFO, "GB启动接收", message);
        if (message && message.type &&
             message.type == utilSrv.msgTypeAppLoginStart) {//任务消息
            bgApp.startApp(); //登入完成的消息通知逻辑  
        }
    });
    */
    //登录完成服务注册业务逻辑
    let isOk = await bgApp.startApp()
    if (!isOk) {//返回失败的情况
        const timerId = setInterval(async()=>{
            isOk = await bgApp.startApp();
            if (isOk) {
                clearInterval(timerId);
            }
        }, 1000*30); //每30秒尝试一次
    }
    chrome.runtime.onInstalled.addListener(()=>{
        ocHeartBeat();
    });
})()