import { DATA_TYPE } from "jsstore";

export const CacheRefType = {tab:'tab', video:'video', cookie:'cookie',
    domain:'domain', task:'task', script:'script', template:'template'};

export const MediaRefType = {image:1, video:2};

export const tbCache = {
    name: 'x_cache',
    columns: {
        skey: {
            primaryKey: true,
            notNull: true,
            dataType: DATA_TYPE.String
        },
        ref_type: {
            notNull: true,
            enableIndex: true,
            dataType: DATA_TYPE.String
        },
        meta: {//自动登录脚本
            notNull: false,
            dataType: DATA_TYPE.Object
        },
        created_at: {
            dataType: DATA_TYPE.Number,
            enableIndex: true,
            notNull: true
        },
    }
};

export const tbItems = {
    name: 'x_items',
    columns: {
        sn: {
            primaryKey: true,
            notNull: true,
            dataType: DATA_TYPE.String
        },
        domain: {
            enableIndex: true,
            dataType: DATA_TYPE.String
        },
        meta: {
            notNull: false,
            dataType: DATA_TYPE.Object
        },
        created_at: {
            dataType: DATA_TYPE.Number,
            notNull: true
        },
    }
};

export const tbComments = {
    name: 'x_comments',
    columns: {
        sn: {
            primaryKey: true,
            notNull: true,
            dataType: DATA_TYPE.String
        },
        domain: {
            enableIndex: true,
            dataType: DATA_TYPE.String
        },
        meta: {
            notNull: false,
            dataType: DATA_TYPE.Object
        },
        created_at: {
            dataType: DATA_TYPE.Number,
            notNull: true
        },
    }
};

export const tbMedia = {
    name: 'x_media',
    columns: {
        id: {
            primaryKey: true,
            autoIncrement: true,
            dataType: DATA_TYPE.Number
        },
        ref_type: {
            notNull: true,
            enableIndex: true,
            dataType: DATA_TYPE.Number
        },
        status: {
            notNull: true,
            dataType: DATA_TYPE.Number
        },
        domain: {
            enableIndex: true,
            dataType: DATA_TYPE.String
        },
        md5str: {
            enableIndex: true,
            unique: true,
            dataType: DATA_TYPE.String
        },
        meta: {
            notNull: false,
            dataType: DATA_TYPE.Object
        },
        created_at: {
            dataType: DATA_TYPE.Number,
            notNull: true
        },
    }
};

export const indexDB = {
    name: "x-scraper.v1", 
    version: 3, 
    Limit: 200000,
    tables: [tbCache, tbItems, tbComments, tbMedia]
};
